CREATE TABLE system_settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE minecraft_hosts (id CHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scanner_agents (id CHAR(36) PRIMARY KEY, host_id CHAR(36) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(host_id) REFERENCES minecraft_hosts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE agent_enrollments (token_hash CHAR(128) PRIMARY KEY, expires_at TIMESTAMP(6) NOT NULL, used_by CHAR(36), revoked BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE agent_heartbeats (agent_id CHAR(36) PRIMARY KEY, seen_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(agent_id) REFERENCES scanner_agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE minecraft_servers (id CHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, minecraft_version VARCHAR(80) NOT NULL, loader VARCHAR(80) NOT NULL, loader_version VARCHAR(80), agent_id CHAR(36), generation BIGINT NOT NULL DEFAULT 0, mapping VARCHAR(100), sequence BIGINT NOT NULL DEFAULT 0, policy_revision BIGINT NOT NULL DEFAULT 0, inventory_at TIMESTAMP(6), snapshot_id CHAR(36), revision BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(agent_id) REFERENCES scanner_agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_snapshots (id CHAR(36) PRIMARY KEY, server_id CHAR(36) NOT NULL, agent_id CHAR(36) NOT NULL, generation BIGINT NOT NULL, sequence BIGINT NOT NULL, digest CHAR(128) NOT NULL, entry_count INT NOT NULL, scanned_at TIMESTAMP(6) NOT NULL, committed_at TIMESTAMP(6), payload LONGTEXT NOT NULL, UNIQUE KEY inventory_order(server_id,generation,sequence), FOREIGN KEY(server_id) REFERENCES minecraft_servers(id), FOREIGN KEY(agent_id) REFERENCES scanner_agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_entries (snapshot_id CHAR(36) NOT NULL, batch_index INT NOT NULL, payload LONGTEXT NOT NULL, PRIMARY KEY(snapshot_id,batch_index), FOREIGN KEY(snapshot_id) REFERENCES inventory_snapshots(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mod_projects (id VARCHAR(128) PRIMARY KEY, payload LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mod_versions (id VARCHAR(128) PRIMARY KEY, project_id VARCHAR(128) NOT NULL, payload LONGTEXT NOT NULL, FOREIGN KEY(project_id) REFERENCES mod_projects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mod_dependencies (version_id VARCHAR(128) NOT NULL, dependency_key VARCHAR(200) NOT NULL, payload LONGTEXT NOT NULL, PRIMARY KEY(version_id,dependency_key), FOREIGN KEY(version_id) REFERENCES mod_versions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE server_manifests (server_id CHAR(36) PRIMARY KEY, latest_revision BIGINT NOT NULL, FOREIGN KEY(server_id) REFERENCES minecraft_servers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE manifest_revisions (server_id CHAR(36) NOT NULL, revision BIGINT NOT NULL, payload LONGTEXT NOT NULL, created_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(server_id,revision), FOREIGN KEY(server_id) REFERENCES server_manifests(server_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE classification_overrides (server_id CHAR(36) NOT NULL, sha512 CHAR(128) NOT NULL, classification VARCHAR(30) NOT NULL, reason VARCHAR(1000) NOT NULL, PRIMARY KEY(server_id,sha512), FOREIGN KEY(server_id) REFERENCES minecraft_servers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE personal_profiles (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, name VARCHAR(200) NOT NULL, payload LONGTEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE personal_profile_mods (profile_id CHAR(36) NOT NULL, project_id VARCHAR(128) NOT NULL, payload LONGTEXT NOT NULL, PRIMARY KEY(profile_id,project_id), FOREIGN KEY(profile_id) REFERENCES personal_profiles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE client_devices (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE client_instances (id CHAR(36) PRIMARY KEY, device_id CHAR(36) NOT NULL, name VARCHAR(200) NOT NULL, FOREIGN KEY(device_id) REFERENCES client_devices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credentials (token_hash CHAR(128) PRIMARY KEY, subject_id CHAR(36) NOT NULL, role VARCHAR(20) NOT NULL, device_id CHAR(36), expires_at TIMESTAMP(6) NOT NULL, kind VARCHAR(20) NOT NULL DEFAULT 'access', INDEX credential_subject(subject_id), INDEX credential_device(device_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE synchronization_history (id CHAR(36) PRIMARY KEY, device_id CHAR(36) NOT NULL, server_id CHAR(36) NOT NULL, revision BIGINT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(device_id) REFERENCES client_devices(id), FOREIGN KEY(server_id) REFERENCES minecraft_servers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, target VARCHAR(200) NOT NULL, correlation_id VARCHAR(36), created_at TIMESTAMP(6) NOT NULL, INDEX audit_time(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
